//! # Berry
//!
//! A fast parser for Yarn Berry (v2+) lockfiles.
//!
//! ```
//! let src = concat!(
//!   "# This file is generated by running \"yarn install\" inside your project.\n",
//!   "# Manual changes might be lost - proceed with caution!\n\n",
//!   "__metadata:\n  version: 8\n  cacheKey: 10\n\n",
//!   "\"left-pad@npm:^1.3.0\":\n  version: 1.3.0\n  resolution: \"left-pad@npm:1.3.0\"\n",
//!   "  dependencies:\n    \"@scope/dep\": \"npm:^2.0.0\"\n  languageName: node\n  linkType: hard\n",
//! );
//! let lockfile = berry::parse(src)?;
//! assert_eq!(lockfile.metadata().version, "8");
//! assert!(lockfile.remaining().is_empty());
//! for entry in &lockfile {
//!   assert_eq!(entry.descriptors().first().unwrap().to_string(), "left-pad@npm:^1.3.0");
//!   assert_eq!(entry.version(), Some("1.3.0"));
//!   let dep = entry.dependencies().get("@scope/dep").unwrap();
//!   assert_eq!(dep.ident().scope(), Some("@scope"));
//!   assert_eq!(dep.range(), "npm:^2.0.0");
//! }
//! # Ok::<(), berry::Error>(())
//! ```
//!
//! The parse produces span tables (`u32` offsets into the text) instead of
//! owned strings or maps: a constant number of allocations, independent of the
//! number of entries, and none when [`Buffers`] are reused. Every accessor is
//! a borrowed, `Copy` view.
//!
//! Inputs: [`parse`] (`&str`), [`parse_bytes`] (`&[u8]`, validated as UTF-8)
//! and [`parse_file`] (a path; memory-mapped or read, see its docs for the
//! concurrent-modification contract of mapped files: Yarn rewrites
//! `yarn.lock` in place), each with a `_with`
//! variant that reuses [`Buffers`].
//!
//! Inputs of 2.5 MB and more are parsed in parallel on the current rayon
//! pool; the result is always identical to a sequential parse.
//! `RAYON_NUM_THREADS=1` (or a one-thread `ThreadPool::install`) makes every
//! parse sequential. A parse called from inside a rayon pool whose workers are
//! all busy with long tasks waits for them; latency-sensitive callers should
//! call it from outside the pool.
//!
//! ----
//! This project is not affiliated with Yarn or the Yarn team.
